const seen = new Set();
const output = [];
for (const input of $input.all()) {
  const payload = input.json || {};
  for (const r of (Array.isArray(payload.items) ? payload.items : [])) {
    const videoId = r.id?.videoId;
    if (!videoId || seen.has(videoId)) continue;
    seen.add(videoId);
    output.push({ json: {
      content_id: `youtube_${videoId}`,
      video_id: videoId,
      source: 'YouTube',
      source_url: `https://www.youtube.com/watch?v=${videoId}`,
      title: r.snippet?.title || null,
      description: r.snippet?.description || null,
      author: r.snippet?.channelTitle || null,
      channel_id: r.snippet?.channelId || null,
      published_at: r.snippet?.publishedAt || null,
      thumbnail: r.snippet?.thumbnails?.high?.url || r.snippet?.thumbnails?.default?.url || null,
      content_type: 'video',
      status: 'discovered',
      search_group: input.json.search_group || null,
      raw_search_item: r,
      transcript: null,
      transcript_source: 'pending'
    }});
  }
}
return output;

const base = $('V2 标准化视频对象').item.json;
const stat = $json.items?.[0] || {};
const s = stat.statistics || {};
const views = Number(s.viewCount || 0);
const likes = Number(s.likeCount || 0);
const comments = Number(s.commentCount || 0);
const engagement = views ? (likes + comments) / views : 0;
return { json: { ...base, view_count: views, like_count: likes, comment_count: comments, favorite_count: Number(s.favoriteCount || 0), engagement: { rate: engagement, views, likes, comments }, viral_score: Math.min(100, Math.round((Math.log10(views + 1) * 12 + engagement * 1000) * 100) / 100), raw_statistics_item: stat, status: 'candidate' } };

const base = $('V2 合并指标与热点评分').item.json;
const raw = $json.choices?.[0]?.message?.content || '{}';
let ai;
try { ai = JSON.parse(raw.replace(/^```json\s*/,'').replace(/\s*```$/,'')); } catch (e) { ai = { parse_error: true, error: e.message }; }
const now = new Date().toISOString();
return { json: { ...base, ...ai, status: 'draft', analysis_status: ai.parse_error ? 'parse_failed' : 'complete', analyzed_at: now, preview_ready: Boolean(ai.x_text_en), x_publish_status: 'not_published', visual: { image_url: null, image_source_url: null, processed_image_url: null, image_headline: ai.image_headline || null, asset_subject: ai.asset_subject || null, asset_match_status: ai.asset_match_status || 'pending_official_source', asset_selection_reason: ai.asset_selection_reason || null }, content_visual_binding_key: null } };

const content = $('V2 官方资产绑定与预览字段').item.json;
const raw = content.raw_deepseek_item || {};
return { json: { content_id: content.content_id, route: 'x_image_post', task_type: 'human_review_preview', status: 'queued', input_payload: { source_url: content.source_url, video_id: content.video_id, title: content.title, official_source_url: raw.official_source_url || null, official_image_url: raw.official_image_url || null, content_visual_binding_key: raw.content_visual_binding_key || null }, output_payload: { summary_en: content.summary_en, summary_zh: content.summary_zh, x_text_en: raw.x_text_en || null, official_source_url: raw.official_source_url || null, official_image_url: raw.official_image_url || null, content_visual_binding_key: raw.content_visual_binding_key || null, image_title_overlay_language: raw.image_title_overlay_language || null, image_title_overlay_status: raw.image_title_overlay_status || null, asset_kind: raw.asset_kind || null, asset_selection_reason: raw.asset_selection_reason || null, asset_subject: raw.asset_subject || null, asset_match_status: raw.asset_match_status || null, visual: content.visual || null, preview_ready: content.preview_ready }, created_at: new Date().toISOString(), updated_at: new Date().toISOString() } };

const x = $json;
const raw = x.raw_deepseek_item || {};
const cutoff = Date.parse('2026-08-01T00:00:00Z');
const sourceDate = Date.parse(raw.official_source_published_at || raw.source_published_at || '');
const sourceFresh = Number.isFinite(sourceDate) && sourceDate >= cutoff;
const subjectMatched = raw.asset_match_status === 'subject_matched_official' && Boolean(raw.official_source_url) && Boolean(raw.official_image_url);
const valid = sourceFresh && subjectMatched;
const officialImage = valid ? raw.official_image_url : null;
const officialSource = valid ? raw.official_source_url : null;
const binding = valid ? (raw.content_visual_binding_key || `${x.content_id || x.video_id}|${officialImage}`) : null;
return { json: { ...x, official_image_url: officialImage, official_source_url: officialSource, content_visual_binding_key: binding, image_title_overlay_language: valid ? 'en' : null, image_title_overlay_status: valid ? (raw.image_title_overlay_status || 'official_asset_no_overlay') : null, asset_kind: valid ? (raw.asset_kind || 'official_press_image') : null, asset_selection_reason: valid ? raw.asset_selection_reason : null, asset_subject: valid ? raw.asset_subject : null, asset_match_status: valid ? 'subject_matched_official' : 'needs_manual_visual_review', raw_deepseek_item: { ...raw, official_image_url: officialImage, official_source_url: officialSource, content_visual_binding_key: binding, asset_match_status: valid ? 'subject_matched_official' : 'needs_manual_visual_review', official_source_published_at: raw.official_source_published_at || raw.source_published_at || null } } };

const db = $json;
const raw = db.raw_deepseek_item || {};
const text = String(raw.x_text_en || db.summary_en || '').trim();
const errors = [];
if (db.status !== 'approved') errors.push('not_approved');
if (!raw.official_image_url) errors.push('official_image_url_missing');
if (!raw.official_source_url) errors.push('official_source_url_missing');
if (!raw.content_visual_binding_key) errors.push('content_visual_binding_missing');
if (!text) errors.push('x_text_missing');
if (/^[\s\S]*[\u4e00-\u9fff]/.test(text)) errors.push('x_text_not_english');
return { json: { ...db, official_image_url: raw.official_image_url || null, official_source_url: raw.official_source_url || null, content_visual_binding_key: raw.content_visual_binding_key || null, image_title_overlay_language: raw.image_title_overlay_language || null, x_text_en: text, x_validation_errors: errors, x_publish_status: errors.length ? 'blocked_validation' : 'ready_to_publish' } };

const cutoff = Date.parse('2026-08-01T00:00:00Z');
const MIN_VIEWS = 1000000;
const MIN_LIKES = 10000;
return $input.all().map((item, index) => {
  const x = item.json || {};
  const published = Date.parse(x.published_at || x.publishedAt || '');
  const views = Number(x.view_count || 0);
  const likes = Number(x.like_count || 0);
  return { item, index, published, views, likes };
}).filter(({published, views, likes}) => Number.isFinite(published) && published >= cutoff && views >= MIN_VIEWS && likes >= MIN_LIKES).map(({item, index}) => ({ json: { ...item.json, hotspot_filter: { min_published_at: '2026-08-01T00:00:00Z', min_views: MIN_VIEWS, min_likes: MIN_LIKES, passed: true } }, pairedItem: { item: index } }));

